def is_journal(venue):
    journal_keywords = ['journal', 'transactions', 'artificial intelligence', 'JMLR',
                        'Nature', 'Science', 'IEEE T']
    v_lower = venue.lower() if venue else ''
    return any(k.lower() in v_lower for k in journal_keywords)

def is_arxiv(venue):
    v = venue or ''
    return 'arxiv' in v.lower()

